import pathlib,re,subprocess
paths=[pathlib.Path(p) for p in ['src/features/agent-platform/types.ts','src/features/agent-platform/api.ts','src/features/agent-platform/__tests__/capabilities.test.ts']]
original={p:p.read_bytes() for p in paths}
for p,data in original.items():
    text=data.decode('utf-8')
    header=re.match(r'^/\*\nCopyright \(C\)[\s\S]*?\*/\n+',text).group(0)
    p.write_text(text[len(header):],encoding='utf-8',newline='\n')
try:
    result=subprocess.run(['bun','x','oxfmt','-c','.oxfmtrc.json','--check',*[str(p) for p in paths]],check=False)
finally:
    for p,data in original.items():
        p.write_bytes(data)
raise SystemExit(result.returncode)
